import { Link, useNavigate, useSearchParams } from 'react-router-dom';

import { addArticleAsync } from '@apps/Articles/@services/articles.service';
import ArticlesList from '@apps/Articles/components/ArticlesList';
import Page from '@components/Page';
import PageHeader from '@components/PageHeader';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohContainer from '@ui-kit/layout/Container';

const ArticlesListPage = () => {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();

  return (
    <Page title="Статьи">
      <Breadcrumb data={[{ href: '/articles', text: 'Статьи', active: true }]} />
      <PohContainer>
        <PageHeader title="Статьи">
          <PohButton
            size={ButtonSize.Small}
            variant={ButtonVariant.Success}
            onClick={async () => {
              const name = prompt('Название', '') ?? '';
              const res = await addArticleAsync({ name });
              navigate(`/articles/${res}/edit`);
            }}
          >
            Добавить
          </PohButton>
        </PageHeader>
        <ArticlesList
          {...Object.fromEntries(searchParams)}
          listItemPatcher={(x) => ({
            as: Link,
            to: `/articles/${x.id}`,
          })}
        />
      </PohContainer>
    </Page>
  );
};

export default ArticlesListPage;
